from pathlib import Path
import argparse, gzip, base64, os

ROOT = Path(__file__).resolve().parent

def parse_args():
    ap = argparse.ArgumentParser(description="Build RollamacoasterTycoon R3 as a standalone HTML artifact")
    ap.add_argument("--codex", help="Path to Codex JSON. Defaults to codex.json/codex(1).json/codex*.json beside this builder.")
    ap.add_argument("--output", help="Output HTML path. Defaults beside this builder.")
    return ap.parse_args()

def resolve_codex(explicit=None):
    requested = explicit or os.environ.get("RCT_R3_CODEX")
    if requested:
        path = Path(requested).expanduser()
        if not path.is_absolute():
            path = ROOT / path
        path = path.resolve()
        if not path.is_file():
            raise SystemExit(f"Codex not found: {path}")
        return path
    candidates = [ROOT / "codex.json", ROOT / "codex(1).json"]
    candidates.extend(sorted(ROOT.glob("codex*.json")))
    seen = set()
    for path in candidates:
        key = str(path.resolve())
        if key in seen:
            continue
        seen.add(key)
        if path.is_file():
            return path.resolve()
    raise SystemExit(
        "Missing Codex JSON. Put codex.json (or codex(1).json) beside build_rct_r3.py, "
        "or run: python3 build_rct_r3.py --codex /path/to/codex.json"
    )

ARGS = parse_args()
CODEX_PATH = resolve_codex(ARGS.codex)
codex = CODEX_PATH.read_bytes()
b64 = base64.b64encode(gzip.compress(codex, 9, mtime=0)).decode()
