DEV_JS = r"""
// ============================================================================
// R3 DEVELOPMENT TEST LOOP
// ============================================================================
const R3_RELEASE=Object.freeze({id:'__R3_RELEASE__',schema:1,builtBy:'build_rct_r3.py',artifact:'rollamacoasterTycoon_R3_rebuilt.html'});
const DEV_PHASES=['RELEASE','TEST','COMMENTS','CORE DUMP','REVIEW','PLAN','BUILD','RELEASE'];
const dev={sessionId:null,startedAt:Date.now(),phase:0,comments:[],events:[],errors:[],lastDump:null,server:false,serverRoot:'',testResult:'IN PROGRESS'};
(function installDevCapture(){
 const keep=(level,args)=>{try{dev.events.push({time:new Date().toISOString(),level,text:args.map(x=>typeof x==='string'?x:JSON.stringify(x)).join(' ').slice(0,1800)});dev.events=dev.events.slice(-240)}catch{}};
 for(const level of ['log','warn','error']){const base=console[level].bind(console);console[level]=(...args)=>{keep(level,args);base(...args)}}
 addEventListener('error',e=>{dev.errors.push({time:new Date().toISOString(),type:'error',message:String(e.message||''),source:e.filename||'',line:e.lineno||0,column:e.colno||0,stack:e.error?.stack||''});dev.errors=dev.errors.slice(-80)});
 addEventListener('unhandledrejection',e=>{dev.errors.push({time:new Date().toISOString(),type:'unhandledrejection',message:String(e.reason?.message||e.reason||''),stack:e.reason?.stack||''});dev.errors=dev.errors.slice(-80)});
})();
function devId(){return `${R3_RELEASE.id}-${new Date().toISOString().replace(/[:.]/g,'-')}-${Math.random().toString(36).slice(2,7)}`}
function devLocalKey(){return `rct-r3-dev-comments:${R3_RELEASE.id}`}
function devLoad(){try{dev.comments=JSON.parse(localStorage.getItem(devLocalKey())||'[]')}catch{dev.comments=[]}dev.sessionId=sessionStorage.getItem('rct-r3-dev-session')||devId();sessionStorage.setItem('rct-r3-dev-session',dev.sessionId)}
function devSave(){try{localStorage.setItem(devLocalKey(),JSON.stringify(dev.comments.slice(-250)))}catch{}}
function devContext(){const cam=runtime.camera,ctl=runtime.controls,sel=selectedEntityId?entity(selectedEntityId):null,hov=runtime.hover?entity(runtime.hover):null,focus=document.activeElement;return {bootPhase:Boot.phase,toolMode,selectedBuild,buildRotationDeg:Math.round(buildRotation*180/Math.PI),selectedEntity:sel?{id:sel.id,kind:sel.kind,name:item(sel.kind).name,pos:sel.pos}:null,hoveredEntity:hov?{id:hov.id,kind:hov.kind,name:item(hov.kind).name,pos:hov.pos}:null,camera:cam?{position:cam.position.toArray(),target:ctl?.target?.toArray?.()||null,input:{keysDown:[...runtime.cameraKeys],shift:runtime.cameraShift,moveFrames:runtime.cameraMoveFrames,lastMove:runtime.cameraLastMove,lastKeyAt:runtime.cameraLastKeyAt},frameFaults:clone(runtime.frameFaults)}:null,focus:focus?{tag:focus.tagName||'',id:focus.id||'',contentEditable:!!focus.isContentEditable}:null,park:{id:state.id,name:state.name,open:state.sim.open,day:state.sim.day,minutes:state.sim.minutes,rate:state.sim.rate,cash:state.economy.cash,guests:state.guests.length,staff:state.staff.length,entities:state.entities.length},construction:{gridStep:GRID_STEP,gridCellHalf:GRID_HALF,pathTileSize:GRID_STEP,entranceSignMode:'fixed-plane-both-faces',signText:state.sign,signFont:state.signFont,gateStyle:state.gateStyle,masonryStyle:state.masonryStyle,bounds:activeParkBounds(),gate:activeParkGate(),wildernessApproach:clone(runtime.wildernessPath?.userData||null),propertyParcels:clone(state.property?.parcels||{}),lastContextAction:clone(runtime.lastContextAction),lastPlacement:clone(runtime.lastPlacement)},ui:{trayOpen:!$('#systemTray')?.classList.contains('hidden'),menuOpen:runtime.menuOpen,menuMode:runtime.menuMode,menuOpenedAt:runtime.menuOpenedAt,lastUserAction:clone(runtime.lastUserAction),lastActionTip:clone(runtime.lastActionTip),entrancePreviewActive:!!runtime.entrancePreview?.canvas?.isConnected,screenshot:clone(runtime.lastScreenshot)},network:{endpoint:ollama.endpoint,model:ollama.model,ssids:clone(state.network.ssids),pa:clone(state.network.pa)},economyFeedback:{lastOperatorTransaction:clone(runtime.lastOperatorTransaction)},visiblePanels:[...document.querySelectorAll('.panel:not(.hidden)')].map(x=>x.id),url:location.href};}
async function devDbSummary(){const names=['saves','ledger','guestBrains','conversations','flockFiles','metadata','codex','alexandria'],out={};for(const n of names){try{out[n]=(await db.all(n)).length}catch(e){out[n]=`ERR:${e.message}`}}return out}
function devSanitizeState(){try{return clone(state)}catch{return JSON.parse(JSON.stringify(state,(k,v)=>typeof v==='function'?undefined:v))}}
async function devCoreDump(reason='manual'){
 const mem=performance.memory?{jsHeapSizeLimit:performance.memory.jsHeapSizeLimit,totalJSHeapSize:performance.memory.totalJSHeapSize,usedJSHeapSize:performance.memory.usedJSHeapSize}:null;
 const dump={kind:'rollamacoaster-r3-core-dump',version:1,release:R3_RELEASE,sessionId:dev.sessionId,capturedAt:new Date().toISOString(),reason,testResult:dev.testResult,phase:DEV_PHASES[dev.phase],boot:{phase:Boot.phase,log:clone(Boot.log)},context:devContext(),performance:{now:performance.now(),memory:mem,frames:runtime.frame,devicePixelRatio,viewport:{width:innerWidth,height:innerHeight}},database:await devDbSummary(),errors:clone(dev.errors),console:clone(dev.events.slice(-120)),comments:clone(dev.comments),recentLedger:(await db.all('ledger')).slice(-100),simulation:devSanitizeState()};
 dev.lastDump=dump;dev.phase=Math.max(dev.phase,3);devRender();await devPost('/api/dev/core-dump',dump,false);return dump;
}
function devDownload(name,data,type='application/json'){const blob=data instanceof Blob?data:new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
async function devPost(path,payload,quiet=true){if(!dev.server)return false;try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw new Error(`HTTP ${r.status}`);return true}catch(e){dev.server=false;if(!quiet)status(`Dev collector unavailable: ${e.message}`);devRender();return false}}
async function devDetectServer(){if(location.protocol==='file:'){dev.server=false;devRender();return}try{const r=await fetch('/api/dev/status',{cache:'no-store'});const d=await r.json();dev.server=!!d.ok;dev.serverRoot=d.root||'';if(dev.server)await devPost('/api/dev/session',{release:R3_RELEASE,sessionId:dev.sessionId,startedAt:new Date(dev.startedAt).toISOString(),userAgent:navigator.userAgent},true)}catch{dev.server=false}devRender()}
async function devAddComment(text=null,type=null){const input=$('#devCommentText'),body=(text??input.value).trim();if(!body)return;const c={id:uid('comment'),release:R3_RELEASE.id,sessionId:dev.sessionId,time:new Date().toISOString(),area:$('#devArea').value,severity:type||$('#devSeverity').value,text:body,context:devContext(),errorsSinceStart:dev.errors.length};dev.comments.push(c);dev.comments=dev.comments.slice(-250);dev.phase=Math.max(dev.phase,2);devSave();if(input&&text===null)input.value='';devRender();await devPost('/api/dev/comment',c,true);pushPulse(`Playtest comment saved · ${c.area}`,'DEV')}
async function devReviewPacket(){const dump=dev.lastDump||await devCoreDump('review-packet');dev.phase=Math.max(dev.phase,4);const packet={kind:'rollamacoaster-r3-review-packet',version:1,release:R3_RELEASE,sessionId:dev.sessionId,createdAt:new Date().toISOString(),workflow:{completedThrough:DEV_PHASES[dev.phase],next:'REVIEW → PLAN → BUILD → RELEASE'},testResult:dev.testResult,comments:clone(dev.comments),coreDump:dump};await devPost('/api/dev/review-packet',packet,false);devDownload(`rct-r3-review-${R3_RELEASE.id}-${dev.sessionId}.json`,packet);devRender();return packet}
function devRender(){if(!$('#devPanel'))return;$('#devRelease').textContent=R3_RELEASE.id;$('#devReleaseLabel').textContent=R3_RELEASE.id;$('#devSession').textContent=dev.sessionId||'—';$('#devServerState').textContent=dev.server?'DEV SERVER CONNECTED':'STANDALONE DOWNLOAD MODE';$('#devServerState').className=`devServer ${dev.server?'on':'off'}`;$('#devRuntimeState').textContent=`${Boot.phase} · ${dev.testResult}`;$('#devPhaseBar').innerHTML=DEV_PHASES.map((p,i)=>`<span class="${i<dev.phase?'done':i===dev.phase?'active':''}">${p}</span>`).join('');$('#devCommentList').innerHTML=dev.comments.length?dev.comments.slice().reverse().map(c=>`<div class="devComment"><b>${esc(c.severity)} · ${esc(c.area)} · ${new Date(c.time).toLocaleTimeString()}</b>${esc(c.text)}<div class="devMeta">${esc(c.context?.toolMode||'')} · ${esc(c.context?.selectedBuild||'')} · ${c.context?.park?.guests??0} guests · ${money(c.context?.park?.cash??0)}</div></div>`).join(''):'<div class="empty">No comments in this release session yet.</div>';if(dev.lastDump)$('#devDumpSummary').textContent=JSON.stringify({capturedAt:dev.lastDump.capturedAt,result:dev.lastDump.testResult,errors:dev.lastDump.errors.length,consoleEvents:dev.lastDump.console.length,db:dev.lastDump.database,park:dev.lastDump.context.park},null,2);$('#devQuick').classList.toggle('recording',dev.phase>=1&&dev.testResult==='IN PROGRESS')}
function bindDevUI(){devLoad();$('#devQuick').onclick=()=>{panel('#devPanel');dev.phase=Math.max(dev.phase,1);devRender()};$('#devAddComment').onclick=()=>devAddComment();$('#devPass').onclick=()=>{dev.testResult='PASS';devAddComment('Marked this playtest checkpoint PASS.','note');devRender()};$('#devFail').onclick=()=>{dev.testResult='FAIL';devAddComment('Marked this playtest checkpoint FAIL.','bug');devRender()};$('#devCoreDump').onclick=async()=>{const d=await devCoreDump('operator-capture');if(!dev.server)devDownload(`rct-r3-core-${R3_RELEASE.id}-${dev.sessionId}.json`,d);status('Development core dump captured.')};$('#devCopyDiag').onclick=async()=>{const d=dev.lastDump||await devCoreDump('copy-diagnostics');await navigator.clipboard.writeText(JSON.stringify(d,null,2));status('Diagnostics copied to clipboard.')};$('#devExportReview').onclick=devReviewPacket;$('#devScreenshot').onclick=()=>{try{runtime.renderer.render(runtime.scene,runtime.camera);const canvas=$('#view'),url=canvas.toDataURL('image/png'),a=document.createElement('a');a.href=url;a.download=`rct-r3-view-${R3_RELEASE.id}-${dev.sessionId}.png`;a.click();runtime.lastScreenshot={time:new Date().toISOString(),width:canvas.width,height:canvas.height,bytes:url.length,mode:'forced-render-dataurl'};status('Rendered diagnostic view captured.')}catch(e){runtime.lastScreenshot={time:new Date().toISOString(),error:String(e?.message||e)};dev.errors.push({time:new Date().toISOString(),type:'screenshot',message:String(e?.message||e),stack:String(e?.stack||'')});status(`Screenshot capture failed: ${e.message}`)}};$('#devClearComments').onclick=()=>{if(confirm('Clear locally retained playtest comments for this release?')){dev.comments=[];devSave();devRender()}};$('#devCommentText').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();devAddComment()}});dev.phase=1;devRender();devDetectServer();}
""".replace('__R3_RELEASE__', RELEASE_ID)
html = html.replace('</style>', DEV_CSS + '\n</style>', 1)
html = html.replace('<button id="saveBtn" class="toolbtn" title="Saves (F9)">💾 <span class="txt">Saves</span></button>', '<button id="saveBtn" class="toolbtn" title="Saves (F9)">💾 <span class="txt">Saves</span></button>\n      <button id="devBtn" class="toolbtn" title="Development Test Bench">🧪 <span class="txt">Test</span></button>', 1)
html = html.replace('<div id="fatal"', DEV_HTML + '\n<div id="fatal"', 1)
html = html.replace('async function boot(){', DEV_JS + '\nasync function boot(){', 1)
html = html.replace("function bindUI(){initPanels();", "function bindUI(){initPanels();bindDevUI();$('#devBtn').onclick=()=>{panel('#devPanel');dev.phase=Math.max(dev.phase,1);devRender()};", 1)
out = Path(ARGS.output).expanduser() if ARGS.output else ROOT / "rollamacoasterTycoon_R3_rebuilt.html"
if not out.is_absolute():
    out = ROOT / out
out = out.resolve()
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(html, encoding="utf-8")
print(f"Built {out} ({out.stat().st_size:,} bytes)")
